style.css:
/* Hide the original Google logo */
img[alt="Google"] {
    display: none !important;
}

/* Insert custom logo */
div[aria-label="Google"]::before {
    content: "";
    background-image: url('https://drive.google.com/uc?export=view&id=1CV14-Ft3ww2LY-fKHOVMSnZfe7T54OyB');
    background-size: contain;
    background-repeat: no-repeat;
    width: 272px; /* Adjust width if needed */
    height: 92px; /* Adjust height if needed */
    display: block;
}
